import socket

def parseUDPpacket(data):
    return data.decode('utf-8')

def resolveName(nameToResolve):
    try:
        ip = socket.gethostbyname(nameToResolve)
        return ip
    except socket.gaierror:
        return None

def sendResponse(requestIP, record):
    response = f"{record}\r\n"
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.sendto(response.encode('utf-8'), (requestIP, 53))
    sock.close()

def UDPMessaging(udp_ip, udp_port):
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    server_socket.bind((udp_ip, udp_port))

    while True:
        data, client_address = server_socket.recvfrom(1024)
        request_data = parseUDPpacket(data)
        name_to_resolve = request_data.split()[1]
        record = resolveName(name_to_resolve)
        if record is not None:
            sendResponse(client_address[0], record)
        else:
            sendResponse(client_address[0], "NXDOMAIN")
